INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (106601, 0, 13161, "やってやるですよ！", 13161, 0, "61_inori_guts", "50％でアルファルピ×2000\nさらに次のイベントへ");
