INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (106001, 0, 23152, "それくらいで\nいいんじゃない？", 23152, 0, "92_kyaru_sad", "ランダムなロールの\nランダムサイン×2");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (106601, 2000, 23161, "今日はツイてるです！", 23161, 1, "62_inori_guts", "50％でアルファルピ×4000\nさらに次のイベントへ");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (105501, 0, 23162, "もうこの辺で……", 23162, 0, "62_ayumi_sad", "挑戦終了");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (105601, 0, 33141, "最後にもうひと勝負！", 33141, 0, "53_ruka_fishing", "10％で★3迷宮遺物×1");
